window.HOEREN_TESTS[74] = {"id":"in-der-reinigung","name":"In der Reinigung","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist die Reinigung Blitzblank. Ihr Anzug ist fertig — aber der Fleck am Ärmel ist leider nicht ganz weggegangen. Er ist nicht ganz weg und nicht größer geworden. Wir haben es zweimal versucht. Sie können ihn trotzdem abholen, wir berechnen nur den halben Preis. Geöffnet bis 19 Uhr. Auf Wiedersehen!","gender":"f","q":"Was ist mit dem Fleck?","opts":["Er ist ganz weg.","Er ist größer geworden.","Er ist nicht ganz weggegangen."],"correct":2},{"transcript":"Hallo Tom, hier ist Markus. Ich brauche meinen schwarzen Anzug für die Hochzeit am Samstag, nicht für ein Vorstellungsgespräch und nicht für die Arbeit, aber er ist total zerknittert und riecht nach Schrank. Kann man den so schnell reinigen lassen? Kennst du eine gute Reinigung, die das über Nacht macht? Ruf zurück, ich bin in Panik!","gender":"m","q":"Wofür braucht Markus den Anzug?","opts":["Für ein Vorstellungsgespräch.","Für eine Hochzeit.","Für die Arbeit."],"correct":1},{"transcript":"Achtung Kunden: Unsere Reinigung bietet ab sofort einen Express-Service. Normale Reinigung dauert drei Tage, aber gegen Aufpreis geht es bis zum nächsten Tag. Hemden bügeln wir auch — fünf Stück für nur 8 Euro. Anzüge reinigen wir weiter. Teppiche reinigen wir leider nicht mehr. Fragen Sie an der Theke!","gender":"m","q":"Was reinigt die Firma nicht mehr?","opts":["Teppiche.","Anzüge.","Hemden."],"correct":0},{"transcript":"Hi Lisa, hier ist Anna. Hey, ich habe Rotwein auf mein Lieblingskleid geschüttet — nicht Kaffee und nicht Öl, direkt vor dem Essen, peinlich! Der Fleck ist riesig. Ich bringe es morgen zur Reinigung. Hoffentlich bekommen sie ihn raus. Kennst du ein Hausmittel für Rotwein? Sag schnell Bescheid, danke!","gender":"f","q":"Was ist auf Annas Kleid?","opts":["Kaffee.","Rotwein.","Öl."],"correct":1},{"transcript":"Liebe Kunden: Bitte holen Sie Ihre Sachen innerhalb von drei Monaten ab. Was länger bei uns liegt, müssen wir leider spenden, wir werfen es nicht weg und verkaufen es nicht. Der Platz fehlt. Bewahren Sie unbedingt Ihren Abholschein auf, ohne ihn geht es nicht. Bei Verlust bringen Sie bitte einen Ausweis mit. Vielen Dank!","gender":"f","q":"Was passiert mit Sachen, die zu lange liegen?","opts":["Sie werden weggeworfen.","Sie werden verkauft.","Sie werden gespendet."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer bringt was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Die Reinigung an der Ecke nimmt heute noch neue Sachen an."},{"speaker":"Lisa","gender":"f","text":"Schön, dass du daran denkst. Nach den Festen ist bei uns einiges schmutzig."},{"speaker":"Lukas","gender":"m","text":"Ich bringe den Anzug. Auf dem Ärmel sitzt ein dunkler Fleck vom Essen."},{"speaker":"Lisa","gender":"f","text":"Ich bringe das Abendkleid. Vor dem Fest muss es wieder ganz glatt sein."},{"speaker":"Lukas","gender":"m","text":"Bringt jemand den großen schweren Teppich zur Theke mit?"},{"speaker":"Lisa","gender":"f","text":"Nein. Den Teppich bringen wir nicht mit. Er ist zu schwer für die Theke."},{"speaker":"Lukas","gender":"m","text":"Tom kam mit nassen Ärmeln aus dem Schnee zurück."},{"speaker":"Lisa","gender":"f","text":"Tom bringt die Winterjacke. Der dicke Stoff braucht eine besonders gründliche Wäsche."},{"speaker":"Lukas","gender":"m","text":"Sara will das Schlafzimmer vor dem Frühling frisch haben."},{"speaker":"Lisa","gender":"f","text":"Sara bringt die Bettdecke. Einmal im Jahr kommt sie in die große Maschine."},{"speaker":"Lukas","gender":"m","text":"Bringen wir die bunten Krawatten auch noch mit?"},{"speaker":"Lisa","gender":"f","text":"Nein. Krawatten bringen wir auch nicht mit. Die bleiben ordentlich im Schrank."},{"speaker":"Lukas","gender":"m","text":"Tim hat nächste Woche mehrere wichtige Termine im Büro."},{"speaker":"Lisa","gender":"f","text":"Tim bringt Hemden zum Bügeln. Ein ganzer Stapel wartet schon auf dem Stuhl."},{"speaker":"Lukas","gender":"m","text":"Dann gehe ich morgen früh als Erster zur Theke."},{"speaker":"Lisa","gender":"f","text":"Ich hänge meine Tasche schon heute Abend an die Tür."}],"options":[{"letter":"a","text":"Mantel"},{"letter":"b","text":"Teppich"},{"letter":"c","text":"Winterjacke"},{"letter":"d","text":"Abendkleid"},{"letter":"e","text":"Vorhänge"},{"letter":"f","text":"Bettdecke"},{"letter":"g","text":"Krawatten"},{"letter":"h","text":"Hemden zum Bügeln"},{"letter":"i","text":"Anzug"}],"items":[{"person":"Lukas","correct":"i"},{"person":"Lisa","correct":"d"},{"person":"Tom","correct":"c"},{"person":"Sara","correct":"f"},{"person":"Tim","correct":"h"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, wann ist mein Mantel fertig? Morgen oder am Samstag, können Sie das sagen?"},{"speaker":"Angestellter","gender":"m","text":"Normal am Donnerstag, nicht morgen und nicht am Samstag."},{"speaker":"Kundin","gender":"f","text":"Geht es schneller, schon morgen?"},{"speaker":"Angestellter","gender":"m","text":"Mit Express morgen, plus 5 Euro. Ohne Express am Donnerstag."},{"speaker":"Kundin","gender":"f","text":"Dann lasse ich ihn bis Donnerstag, ohne Express. Danke."}],"q":"Wann ist der Mantel normal fertig?","opts":["Morgen.","Am Donnerstag.","Am Samstag."],"correct":1},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, was kostet es, ein Hemd zu bügeln? 10 Euro oder 2 Euro, wissen Sie das?"},{"speaker":"Angestellte","gender":"f","text":"Ein Hemd 2 Euro, nicht 10 Euro."},{"speaker":"Kunde","gender":"m","text":"Und fünf Stück, auch 2 Euro?"},{"speaker":"Angestellte","gender":"f","text":"Im Paket nur 8 Euro für fünf Hemden. Also nicht 10 Euro, fünf Stück 8 Euro."},{"speaker":"Kunde","gender":"m","text":"Gut, dann fünf Hemden für 8 Euro. Danke schön."}],"q":"Was kostet das Bügeln von fünf Hemden?","opts":["10 Euro.","2 Euro.","8 Euro."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, bekommen Sie diesen Fleck raus? Ist es Rotwein oder Kaffee?"},{"speaker":"Angestellter","gender":"m","text":"Was ist das für ein Fleck, Rotwein oder Kaffee?"},{"speaker":"Frau","gender":"f","text":"Öl, vom Kochen, nicht Rotwein und nicht Kaffee."},{"speaker":"Angestellter","gender":"m","text":"Ölflecken sind schwer, aber wir versuchen es. Rotwein und Kaffee gehen oft leichter."},{"speaker":"Frau","gender":"f","text":"Bitte versuchen Sie es. Es ist Öl. Danke."}],"q":"Welcher Fleck ist auf der Kleidung?","opts":["Rotwein.","Öl.","Kaffee."],"correct":1},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, ich habe meinen Abholschein verloren, nicht meinen Ausweis und nicht meine Jacke."},{"speaker":"Angestellte","gender":"f","text":"Kein Problem, haben Sie einen Ausweis dabei?"},{"speaker":"Mann","gender":"m","text":"Ja, hier ist der Ausweis. Die Jacke liegt noch bei Ihnen."},{"speaker":"Angestellte","gender":"f","text":"Gut, dann finde ich Ihre Sachen ohne den Abholschein."},{"speaker":"Mann","gender":"m","text":"Danke, der Ausweis reicht also. Den Schein habe ich wirklich verloren."}],"q":"Was hat der Mann verloren?","opts":["Seinen Ausweis.","Seine Jacke.","Seinen Abholschein."],"correct":2},{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, reinigen Sie auch Leder? Dauert das drei Tage oder einen Tag?"},{"speaker":"Angestellter","gender":"m","text":"Ja, aber das dauert länger, nicht drei Tage und nicht einen Tag."},{"speaker":"Kundin","gender":"f","text":"Wie lange dann?"},{"speaker":"Angestellter","gender":"m","text":"Eine Woche, Leder ist empfindlich. Also eine Woche, nicht drei Tage."},{"speaker":"Kundin","gender":"f","text":"Okay, eine Woche ist in Ordnung. Ich hole es nächste Woche. Danke."}],"q":"Wie lange dauert die Leder-Reinigung?","opts":["Eine Woche.","Drei Tage.","Einen Tag."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Özdemir, einer Inhaberin einer Reinigung. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Özdemir, Sie führen Ihre Reinigung seit 18 Jahren. Was bringen die Leute am häufigsten?"},{"speaker":"Özdemir","gender":"f","text":"Anzüge und Hemden, ganz klar — viele Berufstätige haben keine Zeit zum Bügeln. Im Frühling kommen die Winterjacken und Decken, bevor sie in den Schrank kommen. Und vor Festen viele schöne Kleider. Jede Jahreszeit hat ihre eigenen Sachen."},{"speaker":"Reporter","gender":"m","text":"Was ist der schwierigste Fleck?"},{"speaker":"Özdemir","gender":"f","text":"Rotwein und Öl sind sehr hartnäckig. Und alte Flecken, die schon eingetrocknet sind. Mein Tipp: Kommen Sie sofort, nicht erst nach Wochen. Je frischer der Fleck, desto besser bekommen wir ihn raus. Wer wartet, macht es uns schwer."},{"speaker":"Reporter","gender":"m","text":"Versuchen die Leute oft, Flecken selbst zu entfernen?"},{"speaker":"Özdemir","gender":"f","text":"Ja, und das ist meistens ein Fehler. Sie reiben kräftig oder nehmen das falsche Mittel. Dann ist der Stoff kaputt oder der Fleck größer. Bitte fassen Sie empfindliche Sachen nicht selbst an. Bringen Sie sie lieber gleich zu uns, dann ist die Chance am größten."},{"speaker":"Reporter","gender":"m","text":"Wie hat sich Ihr Beruf verändert?"},{"speaker":"Özdemir","gender":"f","text":"Die Leute bügeln heute weniger selbst, das ist gut für uns. Aber sie kaufen auch mehr billige Kleidung, die man nur einmal trägt. Für teure Sachen kommen sie zu uns, für billige nicht. Wir setzen heute auch umweltfreundliche Mittel ein, das war früher anders."},{"speaker":"Reporter","gender":"m","text":"Was raten Sie Ihren Kunden?"},{"speaker":"Özdemir","gender":"f","text":"Lesen Sie das Etikett in der Kleidung. Da steht, wie man sie pflegt. Vieles kann man zu Hause waschen, dafür braucht man uns nicht. Aber bei Anzügen, Leder und empfindlichen Stoffen lohnt sich die Reinigung. Und behandeln Sie gute Kleidung mit Respekt, dann hält sie lange."}],"items":[{"q":"Frau Özdemir rät, mit einem Fleck wochenlang zu warten.","correct":"nein"},{"q":"Im Frühling bringen viele Leute ihre Winterjacken.","correct":"ja"},{"q":"Sie findet, Flecken selbst zu entfernen ist meistens ein Fehler.","correct":"ja"},{"q":"Heute bügeln die Leute viel mehr selbst als früher.","correct":"nein"},{"q":"Sie rät, das Pflege-Etikett in der Kleidung zu lesen.","correct":"ja"}]}]};
